INSERT INTO contract_clauses (id, contract_id, section, text) VALUES ('c01_s0', 'c01', '8.2 Audit & Records', 'Provider shall ensure the Customer retains, for the term of this Agreement and for seven years thereafter, the ability to export a complete, tamper-evident record of all administrative and security-relevant actions in a machine-readable format.');
INSERT INTO contract_clauses (id, contract_id, section, text) VALUES ('c01_s1', 'c01', '4.3 Authentication', 'Provider shall permit the Customer to require that all end-user authentication be brokered through the Customer''s own identity provider using an industry-standard federation protocol.');
INSERT INTO contract_clauses (id, contract_id, section, text) VALUES ('c01_s2', 'c01', '3.4 Fees', 'The Customer shall pay the fees set out in the applicable Order Form within thirty (30) days of invoice.');
INSERT INTO contract_clauses (id, contract_id, section, text) VALUES ('c01_s3', 'c01', '12.1 Limitation of Liability', 'Neither party''s aggregate liability shall exceed the fees paid in the twelve months preceding the claim.');
INSERT INTO contract_clauses (id, contract_id, section, text) VALUES ('c01_s4', 'c01', '2.1 Term', 'This Agreement commences on the Effective Date and continues for the Initial Term unless terminated earlier in accordance with its provisions.');
INSERT INTO contract_clauses (id, contract_id, section, text) VALUES ('c02_s0', 'c02', '5.1 Data Residency (SLA)', 'All Customer Data, including backups, shall be stored and processed exclusively within the geographic region designated by the Customer at onboarding, and shall not be replicated outside that region without prior written consent.');
INSERT INTO contract_clauses (id, contract_id, section, text) VALUES ('c02_s1', 'c02', '12.1 Limitation of Liability', 'Neither party''s aggregate liability shall exceed the fees paid in the twelve months preceding the claim.');
INSERT INTO contract_clauses (id, contract_id, section, text) VALUES ('c02_s2', 'c02', '3.4 Fees', 'The Customer shall pay the fees set out in the applicable Order Form within thirty (30) days of invoice.');
INSERT INTO contract_clauses (id, contract_id, section, text) VALUES ('c02_s3', 'c02', '2.1 Term', 'This Agreement commences on the Effective Date and continues for the Initial Term unless terminated earlier in accordance with its provisions.');
INSERT INTO contract_clauses (id, contract_id, section, text) VALUES ('c02_s4', 'c02', '10.2 Support', 'Provider shall provide support in accordance with the support policy referenced in the Order Form.');
INSERT INTO contract_clauses (id, contract_id, section, text) VALUES ('c03_s0', 'c03', '6.2 Access Control', 'End users shall authenticate exclusively via the Customer''s designated single sign-on identity provider; local password authentication shall be disabled.');
INSERT INTO contract_clauses (id, contract_id, section, text) VALUES ('c03_s1', 'c03', '14.3 Governing Law', 'This Agreement shall be governed by the laws of the jurisdiction specified in the Order Form.');
